  const handleTrialBalanceCsvSelected = async (e: React.ChangeEvent<HTMLInputElement>) => {
    console.log('?? CSV File selected');
    const file = e.target.files?.[0];
    if (!file) {
      console.log('? No file selected');
      return;
    }

    console.log('? File:', file.name, 'Size:', file.size, 'Company:', selectedCompanyId);
    console.log('?? Current User:', currentUser?.email || 'NOT SET');
    setError(null);

    try {
      const fileName = (file.name || '').toLowerCase();
      let text = '';
      if (fileName.endsWith('.csv')) {
        console.log('?? Reading CSV file text...');
        text = await file.text();
      } else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
        console.log('?? Reading Excel file and converting first sheet to CSV...');
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer, { type: 'array' });
        const firstSheetName = workbook.SheetNames?.[0];
        if (!firstSheetName) {
          throw new Error('Excel file has no sheets');
        }
        const firstSheet = workbook.Sheets[firstSheetName];
        text = XLSX.utils.sheet_to_csv(firstSheet);
      } else {
        throw new Error('Unsupported file type. Please upload CSV, XLSX, or XLS.');
      }
      console.log('? File converted, length:', text.length);

      console.log('?? Parsing Trial Balance CSV...');
      const parsed = parseTrialBalanceCSV(text, selectedCompanyId);
      if (!parsed.accounts || parsed.accounts.length === 0) {
        throw new Error('No account rows were detected. Verify the header/date row and that account names are in a text column.');
      }
      console.log('? Parsed successfully:', parsed);

      const csvData = {
        ...parsed,
        _companyId: selectedCompanyId,
        fileName: file.name,
      };

      console.log('?? Setting csvTrialBalanceData state...');
      setCsvTrialBalanceData(csvData);
      setMappingSourceSummary(null);

      console.log('?? Saving to localStorage...');
      localStorage.setItem(`csvTrialBalance_${selectedCompanyId}`, JSON.stringify(csvData));
      setHasSavedCsvInLocalStorage(true);

      setError(null);
      console.log('? CSV upload complete!');
    } catch (err: any) {
      console.error('? Error parsing CSV:', err);
      setError(`Failed to parse Trial Balance file: ${err.message}`);
      setCsvTrialBalanceData(null);
    } finally {
      // allow re-selecting the same file
      e.target.value = '';
    }
  };

  // State - QuickBooks Connection
  const [qbConnected, setQbConnected] = useState(false);

  // State - Xero Connection
  const [xeroConnected, setXeroConnected] = useState(false);
  const [xeroStatus, setXeroStatus] = useState<'ACTIVE' | 'INACTIVE' | 'ERROR' | 'EXPIRED' | 'NOT_CONNECTED'>('NOT_CONNECTED');
  const [xeroLastSync, setXeroLastSync] = useState<Date | null>(null);
  const [xeroSyncing, setXeroSyncing] = useState(false);
  const [xeroError, setXeroError] = useState<string | null>(null);
  
  // State - Infor M3 Connection
  const [inforConnected, setInforConnected] = useState(false);
  const [inforStatus, setInforStatus] = useState<'ACTIVE' | 'INACTIVE' | 'ERROR' | 'EXPIRED' | 'NOT_CONNECTED'>('NOT_CONNECTED');
  const [inforLastSync, setInforLastSync] = useState<Date | null>(null);
  const [inforError, setInforError] = useState<string | null>(null);
  const [inforBusy, setInforBusy] = useState(false);
  const [inforBusyAction, setInforBusyAction] = useState<
    'connect' | 'save_credentials' | 'test_token' | 'probe' | 'disconnect' | 'operational_sync' | 'operational_sync_reset' | null
  >(null);
  const [inforBusyStartedAt, setInforBusyStartedAt] = useState<number | null>(null);
  const [inforCredentials, setInforCredentials] = useState({
    tenantId: '',
    clientName: '',
    clientId: '',
    clientSecret: '',
    ionApiBaseUrl: '',
    ssoBaseUrl: '',
    oauthAuthPath: '',
    oauthTokenPath: '',
    oauthRevokePath: '',
    serviceAccountAccessKey: '',
    serviceAccountSecretKey: '',
  });
  const [inforProbePath, setInforProbePath] = useState('/APR_PRD/CSI/IDORequestService/ido/load/SLCustomers?properties=CustNum,Name&recordCap=1');
  const [inforProbeSummary, setInforProbeSummary] = useState<string | null>(null);
  const [inforOperationalSyncStatus, setInforOperationalSyncStatus] = useState<InforOperationalSyncStatus | null>(null);
  const inforSyncPollFailureCountRef = useRef(0);
  useEffect(() => {
    if (inforBusy && !inforBusyStartedAt) {
      setInforBusyStartedAt(Date.now());
    }
  }, [inforBusy, inforBusyStartedAt]);

  useEffect(() => {
    if (!inforBusy || !inforBusyStartedAt) return;
    // Safety net: clear stale busy state if a request path gets interrupted
    // and never reaches the normal finally block.
    const intervalId = window.setInterval(() => {
      if (Date.now() - inforBusyStartedAt > 2 * 60 * 1000) {
        setInforBusy(false);
        setInforBusyAction(null);
        setInforBusyStartedAt(null);
      }
    }, 15000);
    return () => window.clearInterval(intervalId);
  }, [inforBusy, inforBusyStartedAt]);

  useEffect(() => {
    const currentStatus = inforOperationalSyncStatus;
    if (!currentStatus?.companyId || !currentStatus?.syncRunId) return;
    const shouldPoll = currentStatus.state === 'running';
    if (!shouldPoll) return;
    let cancelled = false;
    const lastProgressMs = currentStatus.lastChunkAt ? new Date(currentStatus.lastChunkAt).getTime() : NaN;
    const secondsSinceProgress = Number.isFinite(lastProgressMs)
      ? Math.max(0, Math.floor((Date.now() - lastProgressMs) / 1000))
      : null;
    const pollIntervalMs = secondsSinceProgress != null && secondsSinceProgress > 120 ? 30000 : 10000;
    const registerPollingFailure = (reason: string) => {
      inforSyncPollFailureCountRef.current += 1;
      if (inforSyncPollFailureCountRef.current < 6) return;
      setInforOperationalSyncStatus((prev) => {
        if (!prev) return prev;
        if (prev.companyId !== currentStatus.companyId || prev.syncRunId !== currentStatus.syncRunId) return prev;
        return {
          ...prev,
          // Polling transport failures should not be reported as run failure.
          state: prev.state === 'running' ? 'running' : prev.state,
          recentlyActive: prev.recentlyActive,
          lastStatusText: prev.lastStatusText || 'warning',
          lastError: reason || prev.lastError,
          message: 'Status polling temporarily failed. Backend sync may still be running. Refresh and verify run status.',
        };
      });
      if (inforBusy && currentStatus.state !== 'running') {
        setInforBusy(false);
        setInforBusyAction(null);
        setInforBusyStartedAt(null);
      }
    };
    const poll = async () => {
      if (document.visibilityState !== 'visible') return;
      try {
        const response = await fetch(
          `/api/infor-m3/operational-sync-status?companyId=${encodeURIComponent(currentStatus.companyId)}&syncRunId=${encodeURIComponent(currentStatus.syncRunId)}`
        );
        const data = await response.json().catch(() => ({}));
        if (cancelled) return;
        if (!response.ok || !data?.ok) {
          const statusText = typeof data?.error === 'string' ? data.error : `status_${response.status}`;
          registerPollingFailure(statusText);
          return;
        }
        inforSyncPollFailureCountRef.current = 0;
        if (data?.runNotFound === true) {
          setInforOperationalSyncStatus((prev) => {
            if (!prev) return prev;
            if (prev.companyId !== currentStatus.companyId || prev.syncRunId !== currentStatus.syncRunId) return prev;
            return null;
          });
          if (inforBusy) {
            setInforBusy(false);
            setInforBusyAction(null);
            setInforBusyStartedAt(null);
          }
          return;
        }
        const apiChunkCount = Number(data.chunkCount || 0);
        const apiRecordsCreated = Number(data.recordsCreated || 0);
        const apiWarningCount = Number(data.warningCount || 0);
        const apiLastStatusText =
          typeof data.lastStatusText === 'string' && data.lastStatusText.trim().length > 0
            ? data.lastStatusText.trim()
            : null;
        const apiLastChunkAt =
          typeof data.lastChunkAt === 'string' && data.lastChunkAt.trim().length > 0 ? data.lastChunkAt : null;
        const apiRecentlyActive = data.recentlyActive === true;
        const apiRunMode =
          typeof data.runMode === 'string' && data.runMode.trim().length > 0
            ? (data.runMode.trim() as InforOperationalSyncStatus['runMode'])
            : null;
        const apiRunMessage =
          typeof data.runMessage === 'string' && data.runMessage.trim().length > 0 ? data.runMessage.trim() : null;
        const apiRunLastError =
          typeof data.runLastError === 'string' && data.runLastError.trim().length > 0
            ? data.runLastError.trim()
            : null;
        const apiDiagnostics =
          data?.diagnostics && typeof data.diagnostics === 'object' && !Array.isArray(data.diagnostics)
            ? {
                failedChunks: Math.max(0, Number((data.diagnostics as any).failedChunks || 0)),
                skippedChunks: Math.max(0, Number((data.diagnostics as any).skippedChunks || 0)),
                failedPrograms: Array.isArray((data.diagnostics as any).failedPrograms)
                  ? ((data.diagnostics as any).failedPrograms as unknown[])
                      .map((entry) => String(entry || '').trim())
                      .filter((entry) => entry.length > 0)
                      .slice(0, 20)
                  : [],
                suggestedRerunWindows: Array.isArray((data.diagnostics as any).suggestedRerunWindows)
                  ? ((data.diagnostics as any).suggestedRerunWindows as any[])
                      .map((entry) => ({
                        startDate: String(entry?.startDate || '').trim(),
                        endDate: String(entry?.endDate || '').trim(),
                        reason: String(entry?.reason || '').trim(),
                      }))
                      .filter((entry) => entry.startDate && entry.endDate)
                      .slice(0, 12)
                  : [],
                staleSourceWarnings: Array.isArray((data.diagnostics as any).staleSourceWarnings)
                  ? ((data.diagnostics as any).staleSourceWarnings as any[])
                      .map((entry) => ({
                        createdAt: String(entry?.createdAt || '').trim(),
                        targetSnapshotDate: String(entry?.targetSnapshotDate || '').trim() || null,
                        message: String(entry?.message || '').trim(),
                        staleSources: Array.isArray(entry?.staleSources)
                          ? (entry.staleSources as unknown[])
                              .map((value) => String(value || '').trim())
                              .filter((value) => value.length > 0)
                              .slice(0, 10)
                          : [],
                        sourceDates:
                          entry?.sourceDates && typeof entry.sourceDates === 'object' && !Array.isArray(entry.sourceDates)
                            ? Object.fromEntries(
                                Object.entries(entry.sourceDates as Record<string, unknown>).map(([key, value]) => [
                                  key,
                                  String(value || '').trim() || null,
                                ])
                              )
                            : {},
                      }))
                      .filter((entry) => entry.message.length > 0)
                      .slice(0, 8)
                  : [],
              }
            : null;
        const apiQueueSignals =
          data?.queueSignals && typeof data.queueSignals === 'object' && !Array.isArray(data.queueSignals)
            ? (() => {
                const normalizedWatchdogState: 'healthy' | 'at_risk' | 'stale' =
                  String((data.queueSignals as any).watchdogState || '').trim().toLowerCase() === 'stale'
                    ? 'stale'
                    : String((data.queueSignals as any).watchdogState || '').trim().toLowerCase() === 'at_risk'
                      ? 'at_risk'
                      : 'healthy';
                return {
                staleThresholdMinutes: Math.max(1, Number((data.queueSignals as any).staleThresholdMinutes || 30)),
                secondsSinceLastChunk: Number.isFinite(Number((data.queueSignals as any).secondsSinceLastChunk))
                  ? Math.max(0, Number((data.queueSignals as any).secondsSinceLastChunk))
                  : null,
                secondsSinceLastTaskAttempt: Number.isFinite(Number((data.queueSignals as any).secondsSinceLastTaskAttempt))
                  ? Math.max(0, Number((data.queueSignals as any).secondsSinceLastTaskAttempt))
                  : null,
                watchdogState: normalizedWatchdogState,
                queueTaskCounts:
                  (data.queueSignals as any).queueTaskCounts &&
                  typeof (data.queueSignals as any).queueTaskCounts === 'object' &&
                  !Array.isArray((data.queueSignals as any).queueTaskCounts)
                    ? {
                        pending: Math.max(0, Number(((data.queueSignals as any).queueTaskCounts as any).pending || 0)),
                        leased: Math.max(0, Number(((data.queueSignals as any).queueTaskCounts as any).leased || 0)),
                        done: Math.max(0, Number(((data.queueSignals as any).queueTaskCounts as any).done || 0)),
                        failed: Math.max(0, Number(((data.queueSignals as any).queueTaskCounts as any).failed || 0)),
                        cancelled: Math.max(0, Number(((data.queueSignals as any).queueTaskCounts as any).cancelled || 0)),
                      }
                    : { pending: 0, leased: 0, done: 0, failed: 0, cancelled: 0 },
                };
              })()
            : null;
        const apiRunTimeline = Array.isArray((data as any)?.runTimeline)
          ? ((data as any).runTimeline as any[])
              .map((entry) => ({
                id: String(entry?.id || '').trim(),
                status: String(entry?.status || '').trim().toLowerCase(),
                chunkCount: Math.max(0, Number(entry?.chunkCount || 0)),
                recordsCreated: Math.max(0, Number(entry?.recordsCreated || 0)),
                warningCount: Math.max(0, Number(entry?.warningCount || 0)),
                retryCount: Math.max(0, Number(entry?.retryCount || 0)),
                lastChunkAt:
                  typeof entry?.lastChunkAt === 'string' && entry.lastChunkAt.trim().length > 0
                    ? entry.lastChunkAt
                    : null,
                updatedAt: String(entry?.updatedAt || '').trim(),
                finishedAt:
                  typeof entry?.finishedAt === 'string' && entry.finishedAt.trim().length > 0
                    ? entry.finishedAt
                    : null,
                secondsSinceProgress: Number.isFinite(Number(entry?.secondsSinceProgress))
                  ? Math.max(0, Number(entry?.secondsSinceProgress))
                  : null,
                isStalled: entry?.isStalled === true,
                isActive: entry?.isActive === true,
              }))
              .filter((entry) => entry.id.length > 0)
              .slice(0, 10)
          : null;
        setInforOperationalSyncStatus((prev) => {
          if (!prev) return prev;
          if (prev.companyId !== currentStatus.companyId || prev.syncRunId !== currentStatus.syncRunId) return prev;
          const normalizedStatus = String(apiLastStatusText || '').toLowerCase();
          const isFailedStatus = normalizedStatus === 'error' || normalizedStatus === 'failed' || normalizedStatus === 'failure';
          const normalizedRunMessage = String(apiRunMessage || '').toLowerCase();
          const hasProblemMessage =
            normalizedRunMessage.includes('failed') ||
            normalizedRunMessage.includes('error') ||
            normalizedRunMessage.includes('skipped stuck chunk');
          const hasProblemSignal =
            Boolean(apiRunLastError) ||
            apiWarningCount > 0 ||
            hasProblemMessage;
          let nextState: InforOperationalSyncStatus['state'];
          if (normalizedStatus === 'running' || normalizedStatus === 'queued') {
            nextState = 'running';
          } else if (normalizedStatus === 'done' || normalizedStatus === 'cancelled') {
            nextState = 'done';
          } else if (isFailedStatus || hasProblemSignal) {
            nextState = 'failed';
          } else {
            nextState = prev.state;
          }
          return {
            ...prev,
            state: nextState,
            runMode: apiRunMode || prev.runMode || null,
            chunkCount: Math.max(prev.chunkCount, apiChunkCount),
            recordsCreated: Math.max(prev.recordsCreated, apiRecordsCreated),
            warningCount: Math.max(prev.warningCount, apiWarningCount),
            lastChunkAt: apiLastChunkAt || prev.lastChunkAt,
            lastStatusText: apiLastStatusText || prev.lastStatusText,
            message: apiRunMessage || prev.message,
            lastError: apiRunLastError || prev.lastError,
            recentlyActive: apiRecentlyActive,
            diagnostics: apiDiagnostics || prev.diagnostics || null,
            queueSignals: apiQueueSignals || prev.queueSignals || null,
            runTimeline: apiRunTimeline || prev.runTimeline || null,
          };
        });
      } catch {
        // Repeated transport failures should not leave status polling in a permanent loop.
        registerPollingFailure('status polling failed');
      }
    };
    void poll();
    const intervalId = window.setInterval(() => {
      void poll();
    }, pollIntervalMs);
    return () => {
      cancelled = true;
      window.clearInterval(intervalId);
    };
  }, [inforBusy, inforOperationalSyncStatus]);

