  const resolveActiveCompanyIdForErpCaoLoad = () => {
    const stateCompanyId = String(selectedCompanyId || '').trim();
    if (stateCompanyId) return stateCompanyId;

    const userCompanyId = String(currentUser?.companyId || '').trim();
    if (userCompanyId) return userCompanyId;

    if (typeof window !== 'undefined') {
      const storedCompanyId = String(localStorage.getItem('fs_selectedCompanyId') || '').trim();
      if (storedCompanyId) return storedCompanyId;

      const activeCompanyCookie = document.cookie
        .split('; ')
        .find((entry) => entry.startsWith('fs_active_company='))
        ?.split('=')[1];
      const cookieCompanyId = String(activeCompanyCookie || '').trim();
      if (cookieCompanyId) return decodeURIComponent(cookieCompanyId);
    }

    const firstCompanyId = String((Array.isArray(companies) && companies[0]?.id) || '').trim();
    return firstCompanyId || '';
  };

  const loadErpCaoInDataMapping = async () => {
    const companyIdForLoad = resolveActiveCompanyIdForErpCaoLoad();
    const selectedSystemNormalized = String(selectedAccountingSystem || '').toUpperCase();
    // Infor CSI should use ERP COA monthly processing (through-month ingest).
    // Keep accounts-only shortcut for classic Infor M3 chart sync.
    const isInforAccountsOnlyLoad = selectedSystemNormalized === 'INFOR_M3';
    console.log('[ERP COA] Load button clicked', {
      selectedCompanyId,
      resolvedCompanyId: companyIdForLoad,
      throughMonth: erpCaoThroughMonth,
      selectedAccountingSystem,
    });
    if (!companyIdForLoad) {
      console.warn('[ERP COA] Blocked before POST: missing companyId');
      alert('Please select a company first.');
      return;
    }
    if (companyIdForLoad !== selectedCompanyId) {
      setSelectedCompanyId(companyIdForLoad);
    }
    if (!isInforAccountsOnlyLoad && !/^\d{4}-\d{2}$/.test(erpCaoThroughMonth)) {
      console.warn('[ERP COA] Blocked before POST: invalid throughMonth', { throughMonth: erpCaoThroughMonth });
      alert('Select a valid Through month first (YYYY-MM).');
      return;
    }
    if (
      !selectedAccountingSystem ||
      !['QUICKBOOKS_DESKTOP', 'INFOR_M3', 'INFOR_CSI'].includes(String(selectedAccountingSystem).toUpperCase())
    ) {
      console.warn('[ERP COA] Blocked before POST: unsupported accounting system', { selectedAccountingSystem });
      alert('ERP COA Load is currently available for QuickBooks Desktop, Infor M3, and Infor SyteLine CSI.');
      return;
    }

    setErpCaoLoading(true);
    try {
      const requestUrl = isInforAccountsOnlyLoad ? '/api/infor-m3/sync-coa' : '/api/erp/coa-load';
      const requestPayload = isInforAccountsOnlyLoad
        ? { companyId: companyIdForLoad }
        : {
            companyId: companyIdForLoad,
            throughMonth: erpCaoThroughMonth,
          };
      console.log('[ERP COA] Sending POST /api/erp/coa-load', {
        requestUrl,
        companyId: companyIdForLoad,
        throughMonth: erpCaoThroughMonth,
      });
      const runCoaLoadRequest = async () => {
        const response = await fetch(requestUrl, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(requestPayload),
        });
        const raw = await response.text();
        const contentType = response.headers.get('content-type') || '';
        const vercelRequestId = response.headers.get('x-vercel-id') || '';
        let result: any = null;
        try {
          result = raw ? JSON.parse(raw) : {};
        } catch {
          result = null;
        }
        if (!result || typeof result !== 'object') {
          const snippet = String(raw || '').slice(0, 220);
          throw new Error(
            `ERP COA endpoint returned non-JSON (status ${response.status}). ` +
              `Request ID: ${vercelRequestId || 'n/a'}. ` +
              `Content-Type: ${contentType || 'n/a'}. ` +
              `Response starts with: ${snippet}`
          );
        }
        return { response, result, vercelRequestId };
      };

      let response: Response;
      let result: any;
      let vercelRequestId = '';
      try {
        ({ response, result, vercelRequestId } = await runCoaLoadRequest());
      } catch (firstError) {
        // Network-level drops (e.g., transient gateway reset) surface as "Failed to fetch".
        // Retry once before surfacing failure to the user.
        console.warn('[ERP COA] First request failed, retrying once', firstError);
        await new Promise((resolve) => setTimeout(resolve, 1500));
        ({ response, result, vercelRequestId } = await runCoaLoadRequest());
      }
      console.log('[ERP COA] Response received', { status: response.status, ok: response.ok, result });
      if (!response.ok || !result?.ok) {
        const details = result?.details ? `\nDetails: ${result.details}` : '';
        throw new Error(
          `${result?.error || result?.message || 'Failed to load ERP COA data'}${details}` +
            (vercelRequestId ? `\nRequest ID: ${vercelRequestId}` : '')
        );
      }

      setQbLastSync(new Date());
      const importedLabel = isInforAccountsOnlyLoad ? 'accounts imported' : 'monthly records processed';
      alert(
        `${isInforAccountsOnlyLoad ? 'ERP COA account load complete.' : `ERP COA load complete. Through month: ${erpCaoThroughMonth}. `}` +
          `${typeof result?.recordsImported === 'number' ? `${result.recordsImported} ${importedLabel}.` : ''}`
      );
      // Refresh mappings in the background so the CTA does not look hung.
      refreshCompanyMappings(companyIdForLoad).catch((refreshError) => {
        console.error('[ERP COA] Background mapping refresh failed', refreshError);
      });
    } catch (error: any) {
      alert(`ERP COA load failed: ${error?.message || 'Unknown error'}`);
    } finally {
      setErpCaoLoading(false);
    }
  };

