  // Infor M3 Functions
  const checkInforM3Status = async (companyId: string) => {
    let timeoutId: number | null = null;
    try {
      const controller = new AbortController();
      const timeoutMs = 15000;
      timeoutId = window.setTimeout(() => controller.abort(), timeoutMs);
      const response = await fetch(`/api/infor-m3/status?companyId=${companyId}`, {
        signal: controller.signal,
      });
      window.clearTimeout(timeoutId);
      timeoutId = null;
      const data = await response.json();

      if (data.connected) {
        setInforConnected(true);
        setInforStatus(data.status);
        setInforLastSync(data.lastSyncAt ? new Date(data.lastSyncAt) : null);
        setInforError(data.errorMessage || null);
        // Rehydrate operational sync panel from backend so refresh/new tab
        // still shows the currently active/queued run for this company.
        try {
          const syncResponse = await fetch(
            `/api/infor-m3/operational-sync-status?companyId=${encodeURIComponent(companyId)}`
          );
          const syncData = await syncResponse.json().catch(() => ({}));
          if (syncResponse.ok && syncData?.ok) {
            const syncRunId = String(syncData.syncRunId || '').trim();
            if (syncRunId && syncData.runNotFound !== true) {
              const runStatus = String(syncData.runStatus || syncData.lastStatusText || '').trim().toLowerCase();
              const nextState: InforOperationalSyncStatus['state'] =
                runStatus === 'failed' || runStatus === 'error'
                  ? 'failed'
                  : runStatus === 'done' || runStatus === 'cancelled'
                    ? 'done'
                    : 'running';
              const diagnostics =
                syncData?.diagnostics && typeof syncData.diagnostics === 'object' && !Array.isArray(syncData.diagnostics)
                  ? {
                      failedChunks: Math.max(0, Number((syncData.diagnostics as any).failedChunks || 0)),
                      skippedChunks: Math.max(0, Number((syncData.diagnostics as any).skippedChunks || 0)),
                      failedPrograms: Array.isArray((syncData.diagnostics as any).failedPrograms)
                        ? ((syncData.diagnostics as any).failedPrograms as unknown[])
                            .map((entry) => String(entry || '').trim())
                            .filter((entry) => entry.length > 0)
                            .slice(0, 20)
                        : [],
                      suggestedRerunWindows: Array.isArray((syncData.diagnostics as any).suggestedRerunWindows)
                        ? ((syncData.diagnostics as any).suggestedRerunWindows as any[])
                            .map((entry) => ({
                              startDate: String(entry?.startDate || '').trim(),
                              endDate: String(entry?.endDate || '').trim(),
                              reason: String(entry?.reason || '').trim(),
                            }))
                            .filter((entry) => entry.startDate && entry.endDate)
                            .slice(0, 12)
                        : [],
                      staleSourceWarnings: Array.isArray((syncData.diagnostics as any).staleSourceWarnings)
                        ? ((syncData.diagnostics as any).staleSourceWarnings as any[])
                            .map((entry) => ({
                              createdAt: String(entry?.createdAt || '').trim(),
                              targetSnapshotDate: String(entry?.targetSnapshotDate || '').trim() || null,
                              message: String(entry?.message || '').trim(),
                              staleSources: Array.isArray(entry?.staleSources)
                                ? (entry.staleSources as unknown[])
                                    .map((value) => String(value || '').trim())
                                    .filter((value) => value.length > 0)
                                    .slice(0, 10)
                                : [],
                              sourceDates:
                                entry?.sourceDates && typeof entry.sourceDates === 'object' && !Array.isArray(entry.sourceDates)
                                  ? Object.fromEntries(
                                      Object.entries(entry.sourceDates as Record<string, unknown>).map(([key, value]) => [
                                        key,
                                        String(value || '').trim() || null,
                                      ])
                                    )
                                  : {},
                            }))
                            .filter((entry) => entry.message.length > 0)
                            .slice(0, 8)
                        : [],
                    }
                  : null;
              const queueSignals =
                syncData?.queueSignals && typeof syncData.queueSignals === 'object' && !Array.isArray(syncData.queueSignals)
                  ? (() => {
                      const normalizedWatchdogState: 'healthy' | 'at_risk' | 'stale' =
                        String((syncData.queueSignals as any).watchdogState || '').trim().toLowerCase() === 'stale'
                          ? 'stale'
                          : String((syncData.queueSignals as any).watchdogState || '').trim().toLowerCase() === 'at_risk'
                            ? 'at_risk'
                            : 'healthy';
                      return {
                      staleThresholdMinutes: Math.max(1, Number((syncData.queueSignals as any).staleThresholdMinutes || 30)),
                      secondsSinceLastChunk: Number.isFinite(Number((syncData.queueSignals as any).secondsSinceLastChunk))
                        ? Math.max(0, Number((syncData.queueSignals as any).secondsSinceLastChunk))
                        : null,
                      secondsSinceLastTaskAttempt: Number.isFinite(Number((syncData.queueSignals as any).secondsSinceLastTaskAttempt))
                        ? Math.max(0, Number((syncData.queueSignals as any).secondsSinceLastTaskAttempt))
                        : null,
                      watchdogState: normalizedWatchdogState,
                      queueTaskCounts:
                        (syncData.queueSignals as any).queueTaskCounts &&
                        typeof (syncData.queueSignals as any).queueTaskCounts === 'object' &&
                        !Array.isArray((syncData.queueSignals as any).queueTaskCounts)
                          ? {
                              pending: Math.max(0, Number(((syncData.queueSignals as any).queueTaskCounts as any).pending || 0)),
                              leased: Math.max(0, Number(((syncData.queueSignals as any).queueTaskCounts as any).leased || 0)),
                              done: Math.max(0, Number(((syncData.queueSignals as any).queueTaskCounts as any).done || 0)),
                              failed: Math.max(0, Number(((syncData.queueSignals as any).queueTaskCounts as any).failed || 0)),
                              cancelled: Math.max(0, Number(((syncData.queueSignals as any).queueTaskCounts as any).cancelled || 0)),
                            }
                          : { pending: 0, leased: 0, done: 0, failed: 0, cancelled: 0 },
                      };
                    })()
                  : null;
              const runTimeline = Array.isArray((syncData as any)?.runTimeline)
                ? ((syncData as any).runTimeline as any[])
                    .map((entry) => ({
                      id: String(entry?.id || '').trim(),
                      status: String(entry?.status || '').trim().toLowerCase(),
                      chunkCount: Math.max(0, Number(entry?.chunkCount || 0)),
                      recordsCreated: Math.max(0, Number(entry?.recordsCreated || 0)),
                      warningCount: Math.max(0, Number(entry?.warningCount || 0)),
                      retryCount: Math.max(0, Number(entry?.retryCount || 0)),
                      lastChunkAt:
                        typeof entry?.lastChunkAt === 'string' && entry.lastChunkAt.trim().length > 0
                          ? entry.lastChunkAt
                          : null,
                      updatedAt: String(entry?.updatedAt || '').trim(),
                      finishedAt:
                        typeof entry?.finishedAt === 'string' && entry.finishedAt.trim().length > 0
                          ? entry.finishedAt
                          : null,
                      secondsSinceProgress: Number.isFinite(Number(entry?.secondsSinceProgress))
                        ? Math.max(0, Number(entry?.secondsSinceProgress))
                        : null,
                      isStalled: entry?.isStalled === true,
                      isActive: entry?.isActive === true,
                    }))
                    .filter((entry) => entry.id.length > 0)
                    .slice(0, 10)
                : null;
              setInforOperationalSyncStatus({
                companyId,
                syncRunId,
                state: nextState,
                runMode:
                  typeof syncData.runMode === 'string' && syncData.runMode.trim().length > 0
                    ? (syncData.runMode.trim() as InforOperationalSyncStatus['runMode'])
                    : null,
                chunkCount: Math.max(0, Number(syncData.chunkCount || 0)),
                recordsCreated: Math.max(0, Number(syncData.recordsCreated || 0)),
                warningCount: Math.max(0, Number(syncData.warningCount || 0)),
                lastChunkAt:
                  typeof syncData.lastChunkAt === 'string' && syncData.lastChunkAt.trim().length > 0
                    ? syncData.lastChunkAt
                    : null,
                lastStatusText:
                  typeof syncData.lastStatusText === 'string' && syncData.lastStatusText.trim().length > 0
                    ? syncData.lastStatusText
                    : null,
                message:
                  typeof syncData.runMessage === 'string' && syncData.runMessage.trim().length > 0
                    ? syncData.runMessage
                    : null,
                lastError:
                  typeof syncData.runLastError === 'string' && syncData.runLastError.trim().length > 0
                    ? syncData.runLastError
                    : null,
                recentlyActive: syncData.recentlyActive === true,
                diagnostics,
                queueSignals,
                runTimeline,
              });
            } else {
              setInforOperationalSyncStatus((prev) => (prev && prev.companyId === companyId ? null : prev));
            }
          }
        } catch {
          // Keep connector status functional even if sync-status hydration fails.
        }
      } else {
        setInforConnected(false);
        setInforStatus('NOT_CONNECTED');
        setInforLastSync(null);
        setInforError(null);
      }
      return data;
    } catch (error) {
      console.error('Failed to check Infor M3 status:', error);
      setInforError('Failed to check Infor M3 connection status');
      return null;
    } finally {
      if (timeoutId !== null) {
        window.clearTimeout(timeoutId);
      }
    }
  };

  const loadInforM3Credentials = async (companyId: string) => {
    try {
      const response = await fetch(`/api/infor-m3/credentials?companyId=${companyId}`);
      const data = await response.json();
      if (!response.ok || !data?.ok) return;
      if (!data?.credentials) return;
      setInforCredentials({
        tenantId: data.credentials.tenantId || '',
        clientName: data.credentials.clientName || '',
        clientId: data.credentials.clientId || '',
        clientSecret: data.credentials.clientSecret || '',
        ionApiBaseUrl: data.credentials.ionApiBaseUrl || '',
        ssoBaseUrl: data.credentials.ssoBaseUrl || '',
        oauthAuthPath: data.credentials.oauthAuthPath || '',
        oauthTokenPath: data.credentials.oauthTokenPath || '',
        oauthRevokePath: data.credentials.oauthRevokePath || '',
        serviceAccountAccessKey: data.credentials.serviceAccountAccessKey || '',
        serviceAccountSecretKey: data.credentials.serviceAccountSecretKey || '',
      });
    } catch (error) {
      console.error('Failed to load Infor M3 credentials:', error);
    }
  };

  const connectInforM3 = async (targetCompanyId?: string) => {
    const companyId = targetCompanyId || selectedCompanyId;
    if (!companyId) {
      alert('Please select a company first');
      return;
    }

    const requiredFields: Array<keyof typeof inforCredentials> = [
      'tenantId',
      'clientId',
      'clientSecret',
      'ionApiBaseUrl',
      'ssoBaseUrl',
      'serviceAccountAccessKey',
      'serviceAccountSecretKey',
    ];
    const missing = requiredFields.filter((field) => !inforCredentials[field]?.trim());
    if (missing.length > 0) {
      alert(`Missing required Infor M3 fields: ${missing.join(', ')}`);
      return;
    }

    setInforBusyAction('connect');
    setInforBusy(true);
    setInforBusyStartedAt(Date.now());
    setInforError(null);
    setInforProbeSummary(null);
    try {
      const response = await fetch('/api/infor-m3/connect', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          companyId,
          ...inforCredentials,
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) {
        throw new Error(data.details || data.error || 'Infor M3 connect failed');
      }

      await checkInforM3Status(companyId);
      alert('Infor M3 credentials validated and saved for this company.');
    } catch (error: any) {
      console.error('Infor M3 connect error:', error);
      const message = error?.message || 'Failed to connect Infor M3';
      setInforError(message);
      alert(`Failed to connect Infor M3:\n\n${message}`);
    } finally {
      setInforBusy(false);
      setInforBusyAction(null);
      setInforBusyStartedAt(null);
    }
  };

  const saveInforM3Credentials = async (
    targetCompanyId?: string,
    schedule?: { frequency: 'daily' | 'weekly' | 'monthly'; pullTime: string; autoSyncWindowDays?: number }
  ) => {
    const companyId = targetCompanyId || selectedCompanyId;
    if (!companyId) {
      alert('Please select a company first');
      return;
    }

    const requiredFields: Array<keyof typeof inforCredentials> = [
      'tenantId',
      'clientId',
      'clientSecret',
      'ionApiBaseUrl',
      'ssoBaseUrl',
      'serviceAccountAccessKey',
      'serviceAccountSecretKey',
    ];
    const missing = requiredFields.filter((field) => !inforCredentials[field]?.trim());
    if (missing.length > 0) {
      alert(`Missing required Infor M3 fields: ${missing.join(', ')}`);
      return;
    }

    setInforBusyAction('save_credentials');
    setInforBusy(true);
    setInforBusyStartedAt(Date.now());
    setInforError(null);
    try {
      const response = await fetch('/api/infor-m3/save-credentials', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          companyId,
          ...inforCredentials,
          ...(schedule
            ? {
                frequency: schedule.frequency,
                pullTime: schedule.pullTime,
                ...(typeof schedule.autoSyncWindowDays === 'number' && Number.isFinite(schedule.autoSyncWindowDays)
                  ? { autoSyncWindowDays: Math.max(1, Math.floor(schedule.autoSyncWindowDays)) }
                  : {}),
              }
            : {}),
        }),
      });
      const data = await response.json();
      if (!response.ok || !data.ok) {
        throw new Error(data.details || data.error || 'Save failed');
      }
      await checkInforM3Status(companyId);
      alert('Infor M3 credentials saved for this company.');
    } catch (error: any) {
      const message = error?.message || 'Failed to save Infor M3 credentials';
      setInforError(message);
      alert(`Failed to save Infor M3 credentials:\n\n${message}`);
    } finally {
      setInforBusy(false);
      setInforBusyAction(null);
      setInforBusyStartedAt(null);
    }
  };

